const T = () => store.tables;
const tenant = () => T().tenants[0];
const currentUser = () => T().users[0];
const byDesc = (key: string) => (a: Row, b: Row) => (b[key]?.getTime?.() ?? b[key] ?? 0) - (a[key]?.getTime?.() ?? a[key] ?? 0);
const byAsc = (key: string) => (a: Row, b: Row) => (a[key]?.getTime?.() ?? a[key] ?? 0) - (b[key]?.getTime?.() ?? b[key] ?? 0);
const byName = (key = "name") => (a: Row, b: Row) => String(a[key] ?? "").localeCompare(String(b[key] ?? ""), "de");
const like = (value: unknown, query: string) => String(value ?? "").toLowerCase().includes(query.toLowerCase());
const asDate = (value: unknown) => value instanceof Date ? value : value ? new Date(value as string) : undefined;
const fail = (message: string): never => { throw new Error(message); };
const metadataOf = (lead: Row): Record<string, unknown> => lead.metadata && typeof lead.metadata === "object" && !Array.isArray(lead.metadata) ? (lead.metadata as Record<string, unknown>) : {};

function requireLead(publicId: string) { return T().leads.find((lead) => lead.publicId === publicId) ?? fail("Lead wurde nicht gefunden."); }
/** Strikte Trennung: Leads zum Verkauf (Lead-Operations) und Vertriebskontakte (Pipeline, E-Mail-Kampagnen, Posteingang) liegen in einer Tabelle, werden aber nie gemischt. */
const isProspect = (row: Row) => row.kind === "vertrieb";
const salesLeads = () => T().leads.filter((row) => !isProspect(row));
const prospects = () => T().leads.filter(isProspect);
function requireSalesLead(publicId: string) { const lead = requireLead(publicId); if (isProspect(lead)) fail("Das ist ein Vertriebskontakt aus der Pipeline – er gehört nicht zu den Leads zum Verkauf."); return lead; }
function requireProspect(publicId: string) { const lead = requireLead(publicId); if (!isProspect(lead)) fail("Das ist ein Lead zum Verkauf – er gehört nicht in die Vertriebspipeline."); return lead; }
function selectedLeads(publicIds: string[], kind: "verkauf" | "vertrieb" = "verkauf") { const selected = new Set(publicIds); return (kind === "vertrieb" ? prospects() : salesLeads()).filter((lead) => selected.has(lead.publicId)); }
function statusEvent(leadId: number, previousStatus: string | null, nextStatus: string, note: string) { insert(store, "leadStatusEvents", { tenantId: tenant().id, leadId, previousStatus, nextStatus, note, actorUserId: currentUser().id, occurredAt: new Date() }); }
function claimEvent(claimId: number, values: Record<string, unknown>) { insert(store, "claimEvents", { tenantId: tenant().id, claimId, previousStatus: null, nextStatus: null, note: null, actorUserId: currentUser().id, occurredAt: new Date(), ...values }); }
function orderEvent(orderId: number, eventType: string, note: string) { insert(store, "orderEvents", { tenantId: tenant().id, orderId, eventType, note, actorUserId: currentUser().id, occurredAt: new Date() }); }

function getDuplicateLeadIds(rows: Row[]) {
  const occurrences = new Map<string, number[]>();
  for (const row of rows) for (const value of [row.email?.trim().toLowerCase(), row.phone?.replace(/\D/g, "")]) if (value && value.length > 2) occurrences.set(value, [...(occurrences.get(value) ?? []), row.id]);
  return new Set(Array.from(occurrences.values()).filter((ids) => ids.length > 1).flat());
}

function deleteLeadCascade(lead: Row, reason: string) {
  const relatedClaims = T().claims.filter((claim) => claim.leadId === lead.id).map((claim) => claim.id);
  const relatedOffers = T().marketplaceOffers.filter((offer) => offer.leadId === lead.id).map((offer) => offer.id);
  remove(store, "claimEvents", (event) => relatedClaims.includes(event.claimId));
  remove(store, "marketplacePriceHistory", (row) => relatedOffers.includes(row.offerId));
  remove(store, "marketplacePurchases", (row) => relatedOffers.includes(row.offerId));
  insert(store, "leadDeletionEvents", { tenantId: tenant().id, publicId: lead.publicId, deletedLeadId: lead.id, deletedByUserId: currentUser().id, reason, occurredAt: new Date() });
  remove(store, "claims", (claim) => claim.leadId === lead.id);
  remove(store, "marketplaceOffers", (offer) => offer.leadId === lead.id);
  remove(store, "leadTagAssignments", (row) => row.leadId === lead.id);
  remove(store, "leadStatusEvents", (row) => row.leadId === lead.id);
  remove(store, "leadDeliveries", (row) => row.leadId === lead.id);
  remove(store, "integrationEvents", (row) => row.leadId === lead.id);
  remove(store, "leads", (row) => row.id === lead.id);
}

function organizationProfileDependencies(profileId: number) {
  const profile = T().organizationProfiles.find((row) => row.id === profileId) ?? fail("Dieses Käufer- oder Lieferantenprofil wurde nicht gefunden.");
  const pickOrder = (order: Row) => ({ id: order.id, orderNumber: order.orderNumber, name: order.name, buyerName: order.buyerName, status: order.status });
  const buyerOrders = T().orders.filter((order) => order.buyerName === profile.name).map(pickOrder);
  let linkedSupplier: Row | undefined; let linkedLeads: Row[] = []; let supplierOrders: Row[] = []; let linkedRules: Row[] = [];
  if (profile.partnerType === "lieferant") {
    linkedSupplier = T().suppliers.find((supplier) => supplier.name === profile.name);
    if (linkedSupplier) {
      const supplierId = linkedSupplier.id;
      linkedLeads = salesLeads().filter((lead) => lead.supplierId === supplierId || lead.supplierName === profile.name).map((lead) => ({ id: lead.id, publicId: lead.publicId, firstName: lead.firstName, lastName: lead.lastName, city: lead.city, status: lead.status }));
      supplierOrders = T().orders.filter((order) => order.supplierId === supplierId).map(pickOrder);
      linkedRules = T().automationRules.filter((rule) => rule.supplierId === supplierId).map((rule) => ({ id: rule.id, name: rule.name, status: rule.status }));
    }
  }
  const linkedOrders = Array.from(new Map([...buyerOrders, ...supplierOrders].map((order) => [order.id, order])).values());
  const picked = { id: profile.id, partnerType: profile.partnerType, name: profile.name, email: profile.email, phone: profile.phone, integrationId: profile.integrationId, status: profile.status, archivedAt: profile.archivedAt, archivedByUserId: profile.archivedByUserId };
  return { profile: picked, raw: profile, linkedSupplier, linkedLeads, linkedOrders, linkedRules };
}

const partnerRecoveryWindowMs = 30 * 24 * 60 * 60 * 1000;

function sanitizeCategoryDraft(value: any) {
  const usedKeys = new Set<string>();
  const fields = (value.fields ?? []).map((field: any, index: number) => {
    const baseKey = String(field.fieldKey ?? "").toLowerCase().replace(/[^a-z0-9_]/g, "_").replace(/^_+|_+$/g, "") || `feld_${index + 1}`;
    let fieldKey = /^[a-z]/.test(baseKey) ? baseKey : `feld_${baseKey}`; fieldKey = fieldKey.slice(0, 120);
    let uniqueKey = fieldKey; let suffix = 2; while (usedKeys.has(uniqueKey)) { uniqueKey = `${fieldKey.slice(0, 116)}_${suffix}`; suffix += 1; } usedKeys.add(uniqueKey);
    return { ...field, fieldKey: uniqueKey, options: field.fieldType === "auswahl" ? (field.options ?? []).filter(Boolean).slice(0, 80) : field.fieldType === "ja_nein" ? ["Ja", "Nein"] : [] };
  });
  const validKeys = new Set(fields.map((field: any) => field.fieldKey));
  const mappings = (value.mappings ?? []).filter((mapping: any) => validKeys.has(mapping.targetFieldKey)).map((mapping: any, index: number) => ({ ...mapping, sortOrder: index }));
  return { ...value, shortcode: String(value.shortcode ?? "").toUpperCase().replace(/[^A-Z0-9ÄÖÜ_-]/g, "_").slice(0, 32), fields, mappings };
}

function simulateExport(integration: Row, lead: Row, externalReference: string) {
  const authMethod = (integration.config as any)?.authMethod;
  if (authMethod !== "ohne" && !integration.credentialsEncrypted) return { eventType: "abgelehnt" as const, externalReference, responseStatus: 401, responseBody: "Zugangsschlüssel fehlt – der Partner hat die Anfrage abgewiesen." };
  const rejected = String(lead.postcode ?? "").startsWith("0");
  return rejected
    ? { eventType: "abgelehnt" as const, externalReference, responseStatus: 422, responseBody: JSON.stringify({ error: "postal_code_not_serviceable", postcode: lead.postcode }) }
    : { eventType: "geliefert" as const, externalReference, responseStatus: 200, responseBody: JSON.stringify({ status: "accepted", reference: externalReference, demo: true }) };
}


