function recordIntegrationExport(integration: Row, lead: Row, externalReference: string) {
  const result = simulateExport(integration, lead, externalReference);
  insert(store, "integrationEvents", { tenantId: tenant().id, integrationId: integration.id, leadId: lead.id, categoryId: lead.categoryId, eventType: result.eventType, amount: null, externalReference: result.externalReference, responseStatus: result.responseStatus, responseBody: result.responseBody, occurredAt: new Date() });
  return result;
}

function resolveBuyerIntegration(config: Row | undefined) {
  if (!config?.buyerUserId) return undefined;
  const membership = T().memberships.find((row) => row.userId === config.buyerUserId && row.status === "aktiv");
  if (!membership?.integrationId) return undefined;
  return T().partnerIntegrations.find((row) => row.id === membership.integrationId && row.status === "aktiv");
}

