function sendDemoEmail(eventId: number) { const event = T().emailEvents.find((row) => row.id === eventId) ?? fail("E-Mail wurde nicht gefunden."); update(store, "emailEvents", (row) => row.id === event.id, { deliveryStatus: "simuliert", sentAt: new Date(), note: "Chat-Demo: Versand simuliert" }); return { ok: true, status: "simuliert", note: "Chat-Demo: Versand simuliert" }; }
