    if (String(event.kind).startsWith("erinnerung") && user?.lastSignedIn && new Date(user.lastSignedIn).getTime() > new Date(membership!.createdAt).getTime()) { update(store, "emailEvents", (row) => row.id === event.id, { deliveryStatus: "übersprungen", note: `Benutzer hat sich am ${new Date(user.lastSignedIn).toLocaleDateString("de-DE")} angemeldet` }); skipped += 1; continue; }
