  const noteLeadId = recipient?.leadId ?? lead?.id ?? null; if (decision.action === "markiert" && assessment?.kind === "interessiert" && settings.markInterest && noteLeadId) insert(store, "pipelineNotes", { tenantId: tenant().id, leadId: noteLeadId, authorUserId: null, text: `KI: Antwort klingt interessiert (${assessment.confidence} %)${assessment.quote ? ` – „${assessment.quote}“` : ""}`, source: "text", dialerCallId: null, createdAt: new Date() });
