/* ---------- Kundenbereich: Helfer (Spiegel von server/customer-area.ts) ---------- */
const effectiveUser = () => (demoSession.impersonatedUserId ? T().users.find((row) => row.id === demoSession.impersonatedUserId) : undefined) ?? currentUser();
const CUSTOMER_PAGES = ["Dashboard", "Leads", "Bestellungen", "Reklamationen", "Lead-Import", "Integrationen", "Support", "Einstellungen"] as const;
function visibleCustomerPages(visibleAreas: unknown, partnerType: string) {
  const areas = Array.isArray(visibleAreas) ? new Set((visibleAreas as unknown[]).map(String)) : null;
  return CUSTOMER_PAGES.filter((page) => ["Dashboard", "Leads", "Einstellungen"].includes(page) || ((areas === null || areas.has(page)) && (page !== "Lead-Import" || partnerType === "lieferant")));
}
/** Eigene Leads des Kunden: als Käufer beliefert (Bestellung oder Stop) oder als Lieferant geliefert – neueste zuerst. */
function ownCustomerLeads(user: Row) {
  const orderIds = new Set(T().orderOperationalConfigs.filter((config) => config.buyerUserId === user.id).map((config) => config.orderId));
  const stopIds = new Set(T().deliveryStops.filter((stop) => stop.buyerUserId === user.id).map((stop) => stop.id));
  const delivered = new Map<number, { at: Date; price: string }>();
  for (const row of T().leadDeliveries) { if (!(row.result === "angeboten" || row.result === "angenommen" || row.result === "reklamiert")) continue; if (!((row.orderId && orderIds.has(row.orderId)) || (row.stopId && stopIds.has(row.stopId)))) continue; const at = new Date(row.occurredAt); const existing = delivered.get(row.leadId); if (!existing || existing.at < at) delivered.set(row.leadId, { at, price: row.unitPrice }); }
  const supplierIds = new Set(T().suppliers.filter((row) => row.userId === user.id || (user.email && row.email === user.email)).map((row) => row.id));
  const rows = salesLeads().filter((row) => delivered.has(row.id) || (row.supplierId && supplierIds.has(row.supplierId)));
  return rows.map((row) => { const delivery = delivered.get(row.id); const claim = [...T().claims].filter((item) => item.leadId === row.id).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0]; return { id: row.id, publicId: row.publicId, name: `${row.firstName ?? ""} ${row.lastName ?? ""}`.trim() || row.publicId, email: row.email ?? "", phone: row.phone ?? "", postcode: row.postcode ?? "", city: row.city ?? "", status: row.status, categoryName: T().leadCategories.find((category) => category.id === row.categoryId)?.name ?? "–", deliveredAt: delivery?.at ?? new Date(row.createdAt), unitPrice: delivery?.price ?? null, claim: claim ? { id: claim.id, status: claim.status, reason: claim.reason } : null, role: delivery ? "käufer" : "lieferant" }; }).sort((a, b) => b.deliveredAt.getTime() - a.deliveredAt.getTime());
}

/* ---------- Lieferkette (Wasserfall): Helfer (Spiegel von server/chain-admin.ts) ---------- */
function chainRangeBounds(range: string, now = new Date()): { from: Date | null; until: Date | null } {
  const today = new Date(now); today.setHours(0, 0, 0, 0);
  if (range === "heute") return { from: today, until: null };
  if (range === "gestern") return { from: new Date(today.getTime() - 86_400_000), until: today };
  if (range === "7_tage") return { from: new Date(today.getTime() - 6 * 86_400_000), until: null };
  if (range === "14_tage") return { from: new Date(today.getTime() - 13 * 86_400_000), until: null };
  if (range === "30_tage") return { from: new Date(today.getTime() - 29 * 86_400_000), until: null };
  return { from: null, until: null };
}
function chainDeliveries(chainId: number, bounds: { from: Date | null; until: Date | null }) {
  return T().leadDeliveries.filter((row) => row.chainId === chainId && (!bounds.from || new Date(row.occurredAt) >= bounds.from) && (!bounds.until || new Date(row.occurredAt) <= bounds.until)).sort((a, b) => new Date(b.occurredAt).getTime() - new Date(a.occurredAt).getTime());
}
function summarizeDeliveries(rows: Row[], now = new Date()) {
  const sent = rows.filter((row) => row.result !== "übersprungen");
  const isAccepted = (row: Row) => row.result === "angenommen" && (Boolean(row.acceptedAt) || !row.windowEndsAt || new Date(row.windowEndsAt).getTime() <= now.getTime());
  const accepted = sent.filter(isAccepted);
  const inWindow = sent.filter((row) => row.result === "angenommen" && !isAccepted(row));
  const rejected = sent.filter((row) => row.result === "abgelehnt" || row.result === "reklamiert"); const reclaimed = sent.filter((row) => row.result === "reklamiert");
  const skipped = rows.filter((row) => row.result === "übersprungen"); const duplicates = skipped.filter((row) => String(row.skipReason ?? "").toLowerCase().startsWith("dublette"));
  const decided = accepted.length + rejected.length;
  return { total: sent.length, accepted: accepted.length, inWindow: inWindow.length, rejected: rejected.length, reclaimed: reclaimed.length, skipped: skipped.length, duplicates: duplicates.length, offered: sent.filter((row) => row.result === "angeboten").length, acceptanceRate: decided ? Math.round((accepted.length / decided) * 100) : null };
}
function chainPickers() {
  const buyers = T().memberships.filter((row) => row.partnerType === "käufer").map((membership) => { const user = T().users.find((row) => row.id === membership.userId); const own = T().deliveryEndpoints.filter((endpoint) => endpoint.membershipId === membership.id && endpoint.enabled !== false); const company = String(user?.company ?? user?.name ?? "Käufer"); return { userId: membership.userId, membershipId: membership.id, label: `${company} — ${user?.name ?? user?.email ?? ""}`, company, contact: String(user?.name ?? ""), email: String(user?.email ?? ""), status: membership.status, api: own.length > 0 || Boolean(membership.integrationId), endpoint: own[0] ? `${own[0].method} ${own[0].url}` : null }; });
  return { buyers, suppliers: T().suppliers.map((supplier) => ({ id: supplier.id, label: supplier.email ? `${supplier.name} — ${supplier.email}` : String(supplier.name), status: supplier.status })), categories: T().leadCategories.map((category) => ({ id: category.id, name: category.name, status: category.status })) };
}
function reorderChainStops(chainId: number, stopIds: number[]) {
  const stops = T().deliveryStops.filter((row) => row.chainId === chainId); const known = new Set(stops.map((stop) => stop.id));
  const ordered = stopIds.filter((id) => known.has(id)); for (const stop of stops) if (!ordered.includes(stop.id)) ordered.push(stop.id);
  ordered.forEach((id, index) => update(store, "deliveryStops", (row) => row.id === id, { position: index + 1 }));
  return { success: true, order: ordered };
}

/** Zeitplaner-Lauf (Spiegel von server/delivery-scheduler.ts): Lieferintervalle, Wiederholungen, Aufgabe nach 3 Versuchen. */
function runScheduledDeliveries(now = new Date()) {
  const settings = deliverySettings();
  const summary = { tenantId: tenant().id, checked: 0, delivered: 0, rejected: 0, skipped: 0, abandoned: 0, details: [] as string[] };
  const pending = salesLeads().filter((lead) => ["neu", "genehmigt"].includes(lead.status) && Number(metadataOf(lead).assignedOrderId) > 0).sort((a, b) => settings.distributionOrder === "lifo" ? new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime() : new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  summary.checked = pending.length; const windowOpened = new Set<number>();
  for (const lead of pending) {
    const orderId = Number(metadataOf(lead).assignedOrderId); const config = T().orderOperationalConfigs.find((row) => row.orderId === orderId); const order = T().orders.find((row) => row.id === orderId);
    if (!order || !config) { summary.skipped += 1; continue; }
    const attempts = T().leadDeliveries.filter((row) => row.leadId === lead.id && row.orderId === orderId && row.result === "abgelehnt");
    if (attempts.length >= 3) { update(store, "leads", (row) => row.id === lead.id, { status: "hängend" }); statusEvent(lead.id, lead.status, "hängend", `Auslieferung an Bestellung ${order.orderNumber} nach ${attempts.length} Versuchen aufgegeben – bitte manuell prüfen.`); summary.abandoned += 1; summary.details.push(`${lead.publicId}: aufgegeben nach ${attempts.length} Versuchen`); continue; }
    const lastAttempt = attempts.reduce<Date | undefined>((latest, row) => { const at = new Date(row.occurredAt); return !latest || latest < at ? at : latest; }, undefined);
    if (lastAttempt && now.getTime() - lastAttempt.getTime() < 30 * 60_000) { summary.skipped += 1; continue; }
    if (config.realtimeDelivery && !attempts.length) { summary.skipped += 1; continue; }
    const lastDelivery = T().leadDeliveries.filter((row) => row.orderId === orderId && (row.result === "angeboten" || row.result === "angenommen")).map((row) => new Date(row.occurredAt)).sort((a, b) => b.getTime() - a.getTime())[0];
    if (!config.realtimeDelivery && !windowOpened.has(orderId) && !intervalWindowOpen(config.deliveryInterval, lastDelivery, now)) { summary.skipped += 1; continue; }
    try { const result = deliverLeadNow(lead, { orderId, now }); if (result.result === "abgelehnt") { summary.rejected += 1; summary.details.push(`${lead.publicId}: abgelehnt (${result.attempts.map((attempt) => attempt.reason ?? attempt.buyerName).join("; ")})`); } else { summary.delivered += 1; windowOpened.add(orderId); summary.details.push(`${lead.publicId}: ${result.result} → ${result.buyerName}`); } }
    catch (error) { summary.skipped += 1; summary.details.push(`${lead.publicId}: ${error instanceof Error ? error.message : "unbekannter Fehler"}`); }
  }
  return summary;
}

function runAutomationsForLead(source: Row, triggerType: string, depth = 0): { duplicated: number; executed: number; delivered: number } {
  const rules = T().automationRules.filter((rule) => rule.status === "aktiv" && rule.triggerType === triggerType && rule.sourceCategoryId === source.categoryId);
  let duplicated = 0; let executed = 0; let delivered = 0;
  const metadata = metadataOf(source);
  const sourceData = { ...metadata, firstName: source.firstName ?? "", lastName: source.lastName ?? "", email: source.email ?? "", phone: source.phone ?? "", postcode: source.postcode ?? "", city: source.city ?? "", status: source.status, supplierName: source.supplierName ?? "" };
  const log = (ruleId: number, result: "ausgeführt" | "übersprungen", summary: string, createdLeadId?: number) => insert(store, "automationExecutionLogs", { tenantId: tenant().id, ruleId, sourceLeadId: source.id, createdLeadId: createdLeadId ?? null, result, summary: summary.slice(0, 320), occurredAt: new Date() });
  const currentLead = () => T().leads.find((row) => row.id === source.id) ?? source;
  for (const rule of rules) {
    try {
      if (rule.supplierId && rule.supplierId !== source.supplierId) { log(rule.id, "übersprungen", "Lieferantenfilter nicht erfüllt"); continue; }
      const fulfilled = conditionsMatch(sourceData, (rule.conditions ?? []) as FieldCondition[], rule.conditionMode); const negative = !fulfilled;
      if (negative && !rule.falseActionType) { log(rule.id, "übersprungen", "Bedingungen nicht erfüllt; kein Negativzweig konfiguriert."); continue; }
      const configSource = negative ? rule.falseActionConfig : rule.actionConfig; const config = configSource && typeof configSource === "object" && !Array.isArray(configSource) ? configSource as Record<string, unknown> : {};
      const actionType = negative ? rule.falseActionType : rule.actionType ?? "lead_typ_duplizieren";
      const textConfig = (key: string) => typeof config[key] === "string" ? config[key] as string : ""; const numericConfig = (key: string) => Number(config[key]) || 0;
      let summary = "Automatisierung ausgeführt."; let createdLeadId: number | undefined;
      if (actionType === "lead_typ_duplizieren") {
        const categoryId = numericConfig("categoryId") || rule.targetCategoryId; const publicId = randomId(8);
        const { id: _sourceId, ...sourceValues } = source; const created = insert(store, "leads", { ...sourceValues, publicId, categoryId, status: "genehmigt", assignedAt: null, createdAt: new Date(), updatedAt: new Date() });
        createdLeadId = created.id; duplicated += 1; summary = `Lead ${publicId} in Zielkategorie ${categoryId} dupliziert`;
        if (depth < 2) { const nested = runAutomationsForLead(created, "lead_erstellt", depth + 1); executed += nested.executed; duplicated += nested.duplicated; delivered += nested.delivered; }
      } else if (actionType === "lead_freigeben" || actionType === "lead_pruefen" || actionType === "lead_status_aendern") {
        const nextStatus = actionType === "lead_freigeben" ? "genehmigt" : actionType === "lead_pruefen" ? "hängend" : textConfig("status");
        if (!["neu", "genehmigt", "zugewiesen", "reklamiert", "fehlerhaft", "deaktiviert", "hängend"].includes(nextStatus)) { log(rule.id, "übersprungen", "Ungültiger Zielstatus in der Aktionskonfiguration."); continue; }
        const before = currentLead().status; update(store, "leads", (row) => row.id === source.id, { status: nextStatus }); if (before !== nextStatus) statusEvent(source.id, before, nextStatus, `Automatisierung: ${rule.name}`); summary = `Leadstatus auf ${nextStatus} gesetzt`;
      } else if (actionType === "lead_sparte_aendern") {
        const categoryId = numericConfig("categoryId") || rule.targetCategoryId; const category = T().leadCategories.find((row) => row.id === categoryId);
        if (!category) { log(rule.id, "übersprungen", "Zielkategorie wurde nicht gefunden."); continue; }
        update(store, "leads", (row) => row.id === source.id, { categoryId }); summary = `Lead-Sparte zu ${category.name} geändert`;
      } else if (actionType === "lead_verantwortung_aendern") {
        const userId = numericConfig("userId"); const member = T().memberships.find((row) => row.userId === userId && row.status === "aktiv");
        if (!member) { log(rule.id, "übersprungen", "Aktives verantwortliches Mitglied wurde nicht gefunden."); continue; }
        update(store, "leads", (row) => row.id === source.id, { assignedUserId: userId, assignedAt: new Date() }); summary = `Verantwortung an ${T().users.find((row) => row.id === userId)?.name ?? `Mitglied #${userId}`} übertragen`;
      } else if (actionType === "lead_tags_setzen") {
        const tagId = numericConfig("tagId"); const tag = T().tags.find((row) => row.id === tagId);
        if (!tag) { log(rule.id, "übersprungen", "Lead-Tag wurde nicht gefunden."); continue; }
        if (!T().leadTagAssignments.some((row) => row.leadId === source.id && row.tagId === tagId)) insert(store, "leadTagAssignments", { leadId: source.id, tagId, createdAt: new Date() }); summary = `Lead-Tag ${tag.name} gesetzt`;
      } else if (actionType === "lead_ausliefern") {
        try { const delivery = deliverLeadNow(currentLead(), {}); summary = delivery.result === "abgelehnt" ? `Auslieferung abgelehnt: ${delivery.attempts.map((attempt) => attempt.reason ?? attempt.buyerName).join("; ")}` : `Automatisch ausgeliefert an ${delivery.buyerName} (${delivery.result})`; if (delivery.result !== "abgelehnt") delivered += 1; }
        catch (error) { log(rule.id, "übersprungen", error instanceof Error ? error.message : "Auslieferung nicht möglich"); continue; }
      } else if (actionType === "lead_lieferkette_zuordnen" || actionType === "lead_bestellung_zuordnen") {
        let chainId: number | null = null; let orderId: number | null = null; let label = "";
        if (actionType === "lead_lieferkette_zuordnen") {
          chainId = numericConfig("chainId") || null; const chain = chainId ? T().deliveryChains.find((row) => row.id === chainId) : undefined;
          if (!chain) { log(rule.id, "übersprungen", "Lieferkette wurde nicht gefunden."); continue; }
          orderId = chain.orderId ?? null; label = `Lieferkette ${chain.name}`;
          update(store, "leads", (row) => row.id === source.id, { metadata: { ...metadataOf(currentLead()), assignedDeliveryChainId: chain.id, assignedDeliveryChainName: chain.name } }); statusEvent(source.id, source.status, source.status, `Automatisierung: Lieferkette zugeordnet (${chain.name})`);
        } else {
          orderId = numericConfig("orderId") || null; const order = orderId ? T().orders.find((row) => row.id === orderId && (row.status === "offen" || row.status === "aktiv")) : undefined;
          if (!order) { log(rule.id, "übersprungen", "Offene Bestellung wurde nicht gefunden."); continue; }
          label = `Bestellung ${order.orderNumber}`;
          update(store, "leads", (row) => row.id === source.id, { metadata: { ...metadataOf(currentLead()), assignedOrderId: order.id, assignedOrderNumber: order.orderNumber } }); statusEvent(source.id, source.status, source.status, `Automatisierung: Bestellung zugeordnet (${order.orderNumber})`);
        }
        summary = `${label} zugeordnet`;
        const orderConfig = orderId ? T().orderOperationalConfigs.find((row) => row.orderId === orderId) : undefined;
        if (!orderId || orderConfig?.realtimeDelivery) {
          try { const delivery = deliverLeadNow(currentLead(), { chainId, orderId }); if (delivery.result === "abgelehnt") summary += `; Auslieferung abgelehnt: ${delivery.attempts.map((attempt) => attempt.reason ?? attempt.buyerName).join("; ")}`; else { delivered += 1; summary += `; ausgeliefert an ${delivery.buyerName}${delivery.export ? ` (API ${delivery.export.integrationName}: HTTP ${delivery.export.responseStatus ?? "–"})` : ""}`; } }
          catch (error) { summary += `; Auslieferung offen: ${error instanceof Error ? error.message : "unbekannter Fehler"}`; }
        }
      } else if (actionType === "integration_ausfuehren") {
        const integrationId = numericConfig("integrationId"); const integration = T().partnerIntegrations.find((row) => row.id === integrationId && row.status === "aktiv");
        if (!integration?.callbackUrl) { log(rule.id, "übersprungen", "Aktive Partnerintegration mit HTTPS-Rückrufadresse fehlt."); continue; }
        const exported = recordIntegrationExport(integration, currentLead(), source.publicId); summary = `Integration ${integration.name}: ${exported.eventType} (HTTP ${exported.responseStatus ?? "–"})`;
      } else if (actionType === "webhook_ausloesen") {
        const url = textConfig("url"); if (!url) { log(rule.id, "übersprungen", "Webhook-URL fehlt."); continue; }
        summary = `Webhook ausgelöst: HTTP 200 (${url}, im Chat-Build simuliert)`;
      } else if (actionType === "nachricht_senden") {
        if (!source.email) { log(rule.id, "übersprungen", "Lead hat keine E-Mail-Adresse für die Nachricht."); continue; }
        insert(store, "emailEvents", { tenantId: tenant().id, templateId: null, recipientEmail: source.email, subject: textConfig("subject") || `Fluxora Lead ${source.publicId}`, deliveryStatus: "entwurf", occurredAt: new Date() }); summary = "Nachrichtenauftrag als Entwurf erstellt";
      } else {
        const actionKey = actionType === "kreditpruefung" ? "creditCheck" : "smartflow"; const actionValue = actionType === "kreditpruefung" ? "angefordert" : textConfig("flowName") || "ausgeführt";
        update(store, "leads", (row) => row.id === source.id, { metadata: { ...metadataOf(currentLead()), [actionKey]: actionValue, lastAutomationRule: rule.name } }); summary = actionType === "kreditpruefung" ? "Kreditprüfung angefordert" : `Smartflow ${actionValue} ausgeführt`;
      }
      log(rule.id, "ausgeführt", negative ? `Trifft nicht zu: ${summary}` : summary, createdLeadId); executed += 1;
    } catch (error) { log(rule.id, "übersprungen", `Fehler: ${error instanceof Error ? error.message : "unbekannt"}`); }
  }
  return { duplicated, executed, delivered };
}

const demoSession = { loggedOut: false, impersonatedUserId: null as number | null };

const AROUNDHOME_PRESET = [{ value: "2", label: "Ungültige Telefonnummer / Spam", reason: "Falsche Telefonnummer" }, { value: "3", label: "Kontaktdaten fehlen / Land nicht unterstützt", reason: "Kontaktdaten fehlen" }, { value: "4", label: "Kein Partner verfügbar", reason: "Kein Partner" }, { value: "5", label: "Kunde existiert bereits (Duplikat)", reason: "Dublette" }, { value: "6", label: "E-Mail auf Sperrliste", reason: "Sperrliste" }];

/** Simulierte Übergabe an die ausgehenden API-Calls des Käufers (URL mit „reject“ → HTTP 422 mit code 5). */
function handOverToBuyerEndpoints(buyerUserId: number, lead: Row) {
  const membership = T().memberships.find((row) => row.userId === buyerUserId); if (!membership) return null;
  const category = T().leadCategories.find((row) => row.id === lead.categoryId);
  const values = leadTemplateValues(lead as any, category ? { name: category.name, shortcode: category.shortcode } : null);
  const targets = selectEndpoints(T().deliveryEndpoints.filter((row) => row.membershipId === membership.id && row.categoryId === lead.categoryId) as any[], lead.supplierId ?? null, values);
  if (!targets.length) return null;
  const settings = memberSettings(membership.id); const results: Array<{ status: number; body: string; ok: boolean; url: string }> = [];
  for (const endpoint of targets) { const rejected = /reject/i.test(endpoint.url) || String(lead.postcode ?? "").startsWith("0"); const body = rejected ? JSON.stringify({ code: 5, message: "duplicate" }) : JSON.stringify({ uuid: `demo-${randomId(8)}` }); results.push({ status: rejected ? 422 : 200, body, ok: !rejected, url: endpoint.url }); update(store, "deliveryEndpoints", (row) => row.id === endpoint.id, { sentCount: (endpoint.sentCount ?? 0) + 1 }); insert(store, "integrationEvents", { tenantId: tenant().id, integrationId: null, endpointId: endpoint.id, leadId: lead.id, categoryId: lead.categoryId, eventType: rejected ? "abgelehnt" : "geliefert", amount: null, externalReference: lead.publicId, responseStatus: rejected ? 422 : 200, responseBody: body, occurredAt: new Date() }); }
  const failed = results.find((row) => !row.ok); const reference = results.find((row) => row.ok)?.body; if (reference) update(store, "leads", (row) => row.id === lead.id, { metadata: { ...metadataOf(lead), partnerReference: JSON.parse(reference).uuid, partnerReferenceAt: new Date().toISOString() } });
  let matchedRule: any = null; if (failed && settings.responseMappingEnabled) { const rule = evaluateResponseRules(T().partnerResponseRules.filter((row) => row.membershipId === membership.id) as any[], failed); if (rule) { const reason = T().reclamationReasons.find((row) => row.id === rule.reasonId); if (reason) matchedRule = { ...rule, reasonName: reason.name, forwardToNextStop: reason.forwardToNextStop ?? true }; } }
  return { ok: !failed, status: (failed ?? results[0]).status, summary: results.map((row) => `${row.url.replace(/^https?:\/\//, "").slice(0, 40)}: HTTP ${row.status}`).join("; "), matchedRule };
}

