/** Übernahme eines Rohdaten-Kontakts als Lead – derselbe Weg wie beim Import (Lead + Verlauf + Automatisierung). */
function convertRawContact(rawContactId: number, options: { actorUserId: number | null; initialStatus: "neu" | "genehmigt"; note: string | null; categoryId?: number | null }) {
  const contact = T().rawContacts.find((row) => row.id === rawContactId) ?? fail("Rohdaten-Kontakt wurde nicht gefunden.");
  if (contact.leadId) { const existing = T().leads.find((row) => row.id === contact.leadId); if (existing) return { leadId: existing.id, publicId: existing.publicId, alreadyConverted: true, automation: null }; }
  const batch = T().rawBatches.find((row) => row.id === contact.batchId) ?? fail("Die Rohdaten-Liste wurde nicht gefunden.");
  const supplier = batch.supplierId ? T().suppliers.find((row) => row.id === batch.supplierId) : null;
  const allowed = Array.from(new Set([batch.categoryId, ...((batch.categoryIds ?? []) as number[])])); const categoryId = options.categoryId ?? contact.categoryId ?? batch.categoryId; if (!allowed.includes(categoryId)) fail("Diese Kategorie ist für die Liste nicht freigegeben.");
  const lead = insert(store, "leads", { tenantId: tenant().id, publicId: randomId(8).toUpperCase(), categoryId, firstName: contact.firstName, lastName: contact.lastName, email: contact.email, phone: contact.phone, postcode: contact.postcode, city: contact.city, country: contact.country ?? "DE", supplierId: supplier?.id ?? null, supplierName: supplier?.name ?? batch.sourceName ?? "Rohdaten (Callcenter)", cost: "0.00", metadata: { ...(contact.data ?? {}), ...(contact.company ? { company: contact.company } : {}), rawContactId: contact.id, rawBatch: batch.name, source: batch.sourceName ?? batch.name }, status: options.initialStatus, assignedUserId: null, createdAt: new Date(), updatedAt: new Date() });
  statusEvent(lead.id, null, options.initialStatus, `Aus Rohdaten übernommen (${batch.name})${options.note ? ` – ${options.note}` : ""}`);
  update(store, "rawContacts", (row) => row.id === contact.id, { status: "konvertiert", leadId: lead.id, categoryId, note: options.note ?? contact.note });
  const automation = runAutomationsForLead(lead, "lead_erstellt");
  if (options.initialStatus === "genehmigt") runAutomationsForLead(T().leads.find((row) => row.id === lead.id) ?? lead, "status_geändert");
  return { leadId: lead.id, publicId: lead.publicId, alreadyConverted: false, automation };
}

