function memberSettings(membershipId: number) {
  const existing = T().memberOperationalSettings.find((row) => row.membershipId === membershipId);
  if (existing) {
    const missing = Object.fromEntries(Object.entries(MEMBER_SETTINGS_DEFAULTS).filter(([key]) => !(key in existing)));
    if (Object.keys(missing).length) update(store, "memberOperationalSettings", (row) => row.membershipId === membershipId, missing);
    return T().memberOperationalSettings.find((row) => row.membershipId === membershipId)!;
  }
  return insert(store, "memberOperationalSettings", { tenantId: tenant().id, membershipId, ...MEMBER_SETTINGS_DEFAULTS });
}

function saveMemberSettings(input: Record<string, unknown>) {
  const { membershipId, ...values } = input as { membershipId: number } & Record<string, unknown>;
  T().memberships.find((row) => row.id === membershipId) ?? fail("Der Benutzer gehört nicht zu diesem Lead-Bereich.");
  memberSettings(membershipId); update(store, "memberOperationalSettings", (row) => row.membershipId === membershipId, values); return { success: true };
}

