    draft.mappings.forEach((mapping: any) => insert(store, "categoryFieldMappings", { tenantId: tenant().id, categoryId: category.id, sourceField: mapping.sourceField, targetFieldKey: mapping.targetFieldKey, mode: mapping.mode, searchValue: mapping.searchValue || null, replaceValue: mapping.replaceValue || null, sortOrder: mapping.sortOrder }));
    return { success: true, categoryId: category.id, fieldCount: draft.fields.length, mappingCount: draft.mappings.length, name: draft.name, shortcode: draft.shortcode, isTemplate: Boolean(input.saveAsTemplate) };
