    fields.forEach((field) => insert(store, "categoryFields", { tenantId: tenant().id, categoryId: category.id, label: field.label, fieldKey: field.fieldKey, fieldType: field.fieldType, options: field.options, required: field.required, visible: field.visible, sortOrder: field.sortOrder }));
